const categories = [
	["Fin", "fin"],
	["Shop", "shop"],
	["News", "news"],
	["Work", "work"],
	["Home", "home"],
	["Travel", "travel"],
	["Health", "health"],
	["School", "school"],
	["Civic", "civic"],
	["Hobby", "hobby"],
] as const;

const subs = [
	["Statements", "statements"],
	["Invoices", "invoices"],
	["Shipping", "shipping"],
	["Returns", "returns"],
	["Letters", "letters"],
] as const;

function organizer(domain: string, folder: string): string {
	return [
		'require ["fileinto", "imap4flags"];',
		"# Generated by email-organizer.",
		`if address :domain :is "From" "${domain}" {`,
		`  fileinto "${folder}";`,
		'  addflag "\\\\Seen";',
		"  stop;",
		"}",
	].join("\n");
}

function extension(address: string, folder: string): string {
	return [
		'require ["include", "environment", "variables", "relational", "comparator-i;ascii-numeric", "spamtest"];',
		`if allof (environment :matches "vnd.proton.origination" "*", address :all :comparator "i;unicode-casemap" :is "From" "${address}") {`,
		`  fileinto "${folder}";`,
		"}",
	].join("\n");
}

function plusOnly(tag: string, folder: string): string {
	return [
		'require ["fileinto", "imap4flags"];',
		"# email-organizer route profile",
		`if address :localpart :matches "To" "*+${tag}" {`,
		`  fileinto "${folder}";`,
		"  stop;",
		"}",
	].join("\n");
}

function plusAndDot(tag: string, folder: string): string {
	return [
		'require ["include", "environment", "fileinto"];',
		`if anyof (address :all :is "To" "owner+${tag}@example.test", address :all :is "To" "owner.${tag}@example.test") {`,
		`  fileinto "${folder}";`,
		"}",
	].join("\n");
}

type ExampleFilter = {
	name: string;
	enabled: boolean;
	sieve: string;
	protonId: string;
};

type ExampleFolder = {
	path: string;
	type: "folder" | "label" | "system";
	protonId: string;
};

export function buildDeclaredFiltersExample(): {
	kind: "declared-filters";
	version: 1;
	provider: "protonmail";
	policy: {
		naming: { folderSlugPattern: string; folderExceptions: string[] };
		safety: {
			protectedPlusAlias: string;
			verificationSenders: string[];
			blockedDestinations: string[];
		};
		keepFirst: string[];
	};
	folders: ExampleFolder[];
	filters: ExampleFilter[];
	observed: {
		filters: { id: string; name: string; enabled: boolean; sieve: string }[];
		folders: {
			id: string;
			path: string;
			name: string;
			type: ExampleFolder["type"];
		}[];
	};
} {
	const folders: ExampleFolder[] = [
		{ path: "Inbox", type: "system", protonId: "fld-inbox" },
		{ path: "Spam", type: "system", protonId: "fld-spam" },
		{ path: "Trash", type: "system", protonId: "fld-trash" },
		{ path: "family", type: "folder", protonId: "fld-family" },
		{ path: "travel", type: "folder", protonId: "fld-travel" },
		{ path: "school", type: "folder", protonId: "fld-school" },
		{ path: "archive", type: "folder", protonId: "fld-archive" },
		{ path: "fin/banking", type: "folder", protonId: "fld-banking" },
		{ path: "fin/investments", type: "folder", protonId: "fld-investments" },
		{ path: "fin/notifications", type: "folder", protonId: "fld-notifications" },
		{ path: "Notification/Alerts", type: "folder", protonId: "fld-alerts" },
		{ path: "Fin/Banking", type: "folder", protonId: "fld-legacy-banking" },
	];
	const filters: ExampleFilter[] = [
		{
			name: "+Owner",
			enabled: true,
			protonId: "flt-01",
			sieve: plusOnly("owner", "Inbox"),
		},
		{
			name: "+Family & .family",
			enabled: true,
			protonId: "flt-02",
			sieve: plusAndDot("family", "family"),
		},
		{
			name: "+Travel",
			enabled: true,
			protonId: "flt-03",
			sieve: plusOnly("travel", "travel"),
		},
		{
			name: "Bot - Archive",
			enabled: true,
			protonId: "flt-04",
			sieve: plusOnly("archive", "archive"),
		},
		{
			name: "+school",
			enabled: true,
			protonId: "flt-05",
			sieve: plusOnly("school", "school"),
		},
		{
			name: "Fin - Notif",
			enabled: true,
			protonId: "flt-06",
			sieve: organizer("notices.fin.example", "fin/notifications"),
		},
		{
			name: "Fin - Investment",
			enabled: true,
			protonId: "flt-07",
			sieve: extension("desk.invest.example", "fin/investments"),
		},
		{
			name: "Fin - Bank",
			enabled: true,
			protonId: "flt-08",
			sieve: organizer("desk.bank.example", "fin/banking"),
		},
		{
			name: "Shop - Coupons",
			enabled: true,
			protonId: "flt-09",
			sieve: organizer("promo.shop.example", "Spam"),
		},
		{
			name: "News - Digests",
			enabled: false,
			protonId: "flt-10",
			sieve: extension("digest.news.example", "news/digests"),
		},
	];
	for (const [category, categorySlug] of categories) {
		for (const [sub, subSlug] of subs) {
			const index = filters.length + 1;
			const path = `${categorySlug}/${subSlug}`;
			if (!folders.some((folder) => folder.path === path)) {
				folders.push({
					path,
					type: "folder",
					protonId: `fld-${categorySlug}-${subSlug}`,
				});
			}
			const domain = `${subSlug}.${categorySlug}.example`;
			filters.push({
				name: `${category} - ${sub}`,
				enabled: true,
				protonId: `flt-${String(index).padStart(2, "0")}`,
				sieve:
					index % 2 === 0
						? organizer(domain, path)
						: extension(`desk@${domain}`, path),
			});
		}
	}
	return {
		kind: "declared-filters",
		version: 1,
		provider: "protonmail",
		policy: {
			naming: {
				folderSlugPattern: "^[a-z0-9]+(?:-[a-z0-9]+)*$",
				folderExceptions: ["Notification", "Alerts"],
			},
			safety: {
				protectedPlusAlias: "owner+*@example.test",
				verificationSenders: ["security.example"],
				blockedDestinations: ["junk"],
			},
			keepFirst: ["+Owner"],
		},
		folders,
		filters,
		observed: {
			filters: filters.map((filter) => ({
				id: filter.protonId,
				name: filter.name,
				enabled: filter.enabled,
				sieve: filter.sieve,
			})),
			folders: folders.map((folder) => ({
				id: folder.protonId,
				path: folder.path,
				name: folder.path.split("/").at(-1) ?? folder.path,
				type: folder.type,
			})),
		},
	};
}
